server {
    listen 443 ssl http2;
    server_name app.example.com;

    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}

func TestHello(t *testing.T) {
    h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        fmt.Fprintln(w, "hi")
    })
    ts := httptest.NewServer(h)
    defer ts.Close()
    res, err := http.Get(ts.URL)
    if err != nil { t.Fatal(err) }
    body, _ := io.ReadAll(res.Body)
    if string(body) != "hi\n" { t.Errorf("got %q", body) }
}

:root {
    --bg:        oklch(18% 0.018 75);
    --bg-elev:   oklch(22% 0.020 75);
    --text:      oklch(94% 0.010 80);
    --text-muted:oklch(72% 0.012 80);
    --accent:    #3ecf8e;
}
body { background: var(--bg); color: var(--text); }

{
  "acls": [
    { "action": "accept", "src": ["tag:admin"], "dst": ["*:*"] },
    { "action": "accept", "src": ["tag:dev"], "dst": ["tag:homelab:80,443,22"] }
  ],
  "tagOwners": {
    "tag:admin": ["autogroup:admin"],
    "tag:homelab": ["autogroup:admin"]
  }
}

PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA foreign_keys = ON;
PRAGMA busy_timeout = 5000;
PRAGMA cache_size = -20000; -- ~20MB
